mapper.select:
/* com.portal.user.policy.ipm.IndvdlInfoPolicyMapper.selectIndvdlInfoPolicyList */ SELECT a.INDVDL_INFO_POLICY_ID AS indvdlInfoId, a.INDVDL_INFO_POLICY_NM AS indvdlInfoNm, a.INDVDL_INFO_POLICY_CN AS indvdlInfoDc, a.INDVDL_INFO_POLICY_AGRE_AT AS indvdlInfoYn, a.FRST_REGISTER_ID AS frstRegisterId, DATE_FORMAT(a.FRST_REGIST_PNTTM, '%Y-%m-%d') AS frstRegistPnttm, ( SELECT m.MBER_NM FROM LETTNGNRLMBER m WHERE m.ESNTL_ID = a.FRST_REGISTER_ID ) AS frstRegisterNm FROM LETTNINDVDLINFOPOLICY a WHERE 1 = 1
AND a.INDVDL_INFO_POLICY_NM LIKE CONCAT('%', #{searchKeyword}, '%')
AND a.INDVDL_INFO_POLICY_CN LIKE CONCAT('%', #{searchKeyword}, '%')
ORDER BY a.FRST_REGIST_PNTTM DESC LIMIT #{recordCountPerPage} OFFSET #{firstIndex}

/* com.portal.user.policy.ipm.IndvdlInfoPolicyMapper.selectIndvdlInfoPolicyListCnt */ SELECT COUNT(*) AS totcnt FROM LETTNINDVDLINFOPOLICY WHERE 1 = 1
AND INDVDL_INFO_POLICY_NM LIKE CONCAT('%', #{searchKeyword}, '%')
AND INDVDL_INFO_POLICY_CN LIKE CONCAT('%', #{searchKeyword}, '%')

mapper.update:
/* com.portal.user.policy.ipm.IndvdlInfoPolicyMapper.updateIndvdlInfoPolicy */
UPDATE LETTNINDVDLINFOPOLICY
   SET INDVDL_INFO_POLICY_NM      = #{indvdlInfoNm},
       INDVDL_INFO_POLICY_CN      = #{indvdlInfoDc},
       INDVDL_INFO_POLICY_AGRE_AT = #{indvdlInfoYn},
       LAST_UPDT_PNTTM            = SYSDATE(),
       LAST_UPDUSR_ID             = #{lastUpdusrId}
 WHERE INDVDL_INFO_POLICY_ID      = #{indvdlInfoId}
